/* Global Styles */

/* Hide landing category items */
.landing-category-select .landing_cat_buttons > .nav-item.n_se::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_im::after,
.landing-category-select .landing_cat_buttons > .nav-item.n_vi::after,
