/* Tags */
#tags .untagged {
  background: var(--ai_chat_buble_a_bg);
}
#tags > .tag,
#tags > .untagged,
#tags #tags-add {
  color: var(--fg-1);
}

/* Prompt Options */
.promptOptionsSelector .default-assistants li.option:hover,
.promptOptionsSelector .recommended-assistants li.option:hover,
.promptOptionsSelector .recommended-assistants li.option[aria-selected="true"],
.promptOptionsSelector .default-assistants li.option[aria-selected="true"],
.promptOptionsSelector .default-assistants li.option.info-show:hover {
