.promptOptionsSelector .custom-assistants span a:hover,
.promptOptionsSelector .custom-assistants li.option.focus,
.promptOptionsSelector .default-assistants .heading:hover,
.promptOptionsSelector .heading:hover,
.promptOptionsSelector li.option.info-show:not(:hover),
.ki-assistants li.option:not(:hover) {
