}

.promptOptionsSelector .default-assistants li.option.focus {
  background-color: var(--ai_chat_buble_a_bg) !important;
}

/* Chat Bubble */
.chat_bubble ol[data-ref-list] .contribution {
  border: 1px solid var(--primary-100);
  border-radius: 4px;
  color: var(--bg-0);
  font-size: .75rem;
  line-height: 1.25rem;
  padding: 0 8px;
  background-color: var(--grey-4) !important;
}
.chat_bubble {
  padding-block: 32px;
  position: relative;
  border: 2px solid var(--dim);
  border-radius: 25px;
  margin-top: 25px;
  margin-bottom: 10px;
  padding: 20px;
  background-color: var(--bg-1);
}
.chat_bubble:focus-within:before,
.chat_bubble:hover:before {
  background-color: unset !important;
}
.chat_bubble .actions {
  display: inline-flex !important;
